gKL(){return"\u0907\u0938\u0938\u0947 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u093f\u0924 \u0938\u092e\u091d\u094c\u0924\u093e \u0930\u0926\u094d\u0926 \u0939\u094b\u0917\u093e\u0964 \u0906\u092a\u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u093f\u092f\u093e \u091c\u093e\u090f\u0917\u093e, \u0917\u094d\u0930\u093e\u0939\u0915 \u0915\u094b \u0938\u0942\u091a\u0928\u093e \u092e\u093f\u0932\u0947\u0917\u0940 \u0914\u0930 \u0907\u0938\u0947 \u092a\u0942\u0930\u094d\u0935\u0935\u0924 \u0928\u0939\u0940\u0902 \u0915\u093f\u092f\u093e \u091c\u093e \u0938\u0915\u0947\u0917\u093e\u0964"},
gKK(){return"\u0930\u0926\u094d\u0926 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u0947\u0902"},
gKN(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0915\u0940 \u0936\u0930\u094d\u0924\u0947\u0902 \u0932\u094b\u0921 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0940\u0902\u0964 \u0915\u0928\u0947\u0915\u094d\u0936\u0928 \u091c\u093e\u0901\u091a\u0915\u0930 \u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0915\u0930\u0947\u0902\u0964"},
gKT(){return"\u0906\u092a\u0915\u093e \u0928\u093f\u0930\u094d\u0923\u092f \u0938\u0939\u0947\u091c\u093e \u0928\u0939\u0940\u0902 \u091c\u093e \u0938\u0915\u093e\u0964 \u0911\u0930\u094d\u0921\u0930 \u0915\u0940 \u092e\u094c\u091c\u0942\u0926\u093e \u0938\u094d\u0925\u093f\u0924\u093f \u091c\u093e\u0901\u091a\u0915\u0930 \u092b\u093f\u0930 \u0915\u094b\u0936\u093f\u0936 \u0915\u0930\u0947\u0902\u0964"},
gKP(){return"\u0938\u0942\u091a\u0928\u093e \u0915\u094b \u092a\u0922\u093c\u093e \u0939\u0941\u0906 \u0928\u0939\u0940\u0902 \u092e\u093e\u0928\u093e \u091c\u093e \u0938\u0915\u093e \u0914\u0930 \u092f\u0939 \u092c\u093e\u0926 \u092e\u0947\u0902 \u092b\u093f\u0930 \u0926\u093f\u0916\u0947\u0917\u0940\u0964"},
gKn(){return"\u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0928\u0947 \u0911\u0930\u094d\u0921\u0930 \u092a\u0930 \u0915\u093e\u092e \u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u0930 \u0932\u093f\u092f\u093e"},
