gKm(){return"\u0915\u093e\u092e \u0936\u0941\u0930\u0942 \u0939\u094b\u0928\u0947 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u093e \u092f\u0939 \u0915\u093e\u092e \u0915\u0930\u0928\u0947 \u0915\u093e \u0905\u0927\u093f\u0915\u093e\u0930 \u0914\u0930 \u0906\u0935\u0936\u094d\u092f\u0915 \u0932\u093e\u0907\u0938\u0947\u0902\u0938 \u092f\u093e \u092a\u0930\u092e\u093f\u091f \u091c\u093e\u0901\u091a\u0947\u0902\u0964 ClearFix \u092f\u0939 \u091c\u093e\u0901\u091a \u0928\u0939\u0940\u0902 \u0915\u0930\u0924\u093e\u0964 \u0936\u0941\u0930\u0942 \u0939\u094b\u0928\u0947 \u0915\u0940 \u0924\u093e\u0930\u0940\u0916 \u0914\u0930 \u0938\u092e\u092f, \u092a\u0939\u0941\u0901\u091a, \u0915\u093e\u0930\u094d\u092f-\u0915\u094d\u0937\u0947\u0924\u094d\u0930 \u0914\u0930 \u0905\u0928\u094d\u092f \u0935\u094d\u092f\u093e\u0935\u0939\u093e\u0930\u093f\u0915 \u092c\u093e\u0924\u0947\u0902 \u092d\u0940 \u092b\u093f\u0930 \u0924\u092f \u0915\u0930\u0947\u0902\u0964"},
gRF(){return"\u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0905\u092c \u092e\u093e\u0928\u094d\u092f \u0928\u0939\u0940\u0902 \u0939\u0948"},
RD(a,b){return a+" \u0928\u0947 \u0911\u0930\u094d\u0921\u0930 \u201c"+b+"\u201d \u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0935\u093e\u092a\u0938 \u0932\u0947 \u0932\u093f\u092f\u093e \u0939\u0948\u0964"},
gRE(){return"\u0911\u0930\u094d\u0921\u0930 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0939\u0948\u0964 \u0915\u094b\u0908 \u0905\u0928\u094d\u092f \u0938\u0915\u094d\u0930\u093f\u092f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u091a\u0941\u0928\u0947\u0902 \u092f\u093e \u0928\u090f \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935\u094b\u0902 \u0915\u0940 \u092a\u094d\u0930\u0924\u0940\u0915\u094d\u0937\u093e \u0915\u0930\u0947\u0902\u0964"},
gQA(){return"\u0917\u094d\u0930\u093e\u0939\u0915 \u0928\u0947 \u0906\u092a\u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0905\u0938\u094d\u0935\u0940\u0915\u093e\u0930 \u0915\u093f\u092f\u093e"},
Qy(a){return"\u0911\u0930\u094d\u0921\u0930 \u201c"+a+"\u201d \u0915\u093e \u0906\u092a\u0915\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u0905\u092c \u0938\u0915\u094d\u0930\u093f\u092f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964"},
gQz(){return"\u0915\u094b\u0908 \u092a\u094d\u0930\u0924\u093f\u092c\u0926\u094d\u0927\u0924\u093e \u0928\u0939\u0940\u0902 \u092c\u0928\u0940\u0964 \u092f\u0926\u093f \u0911\u0930\u094d\u0921\u0930 \u0905\u092d\u0940 \u092d\u0940 \u092a\u094d\u0930\u0915\u093e\u0936\u093f\u0924 \u0939\u0948, \u0924\u094b \u0906\u092a \u0928\u092f\u093e \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u092d\u0947\u091c \u0938\u0915\u0924\u0947 \u0939\u0948\u0902; \u090f\u0915 \u0911\u0930\u094d\u0921\u0930 \u0915\u0947 \u0932\u093f\u090f \u0905\u0927\u093f\u0915\u0924\u092e 5 \u092a\u094d\u0930\u0938\u094d\u0924\u093e\u0935 \u092d\u0947\u091c\u0947 \u091c\u093e \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964"},
gQm(){return"\u0911\u0930\u094d\u0921\u0930 \u0915\u093f\u0938\u0940 \u0905\u0928\u094d\u092f \u0938\u0947\u0935\u093e \u092a\u094d\u0930\u0926\u093e\u0924\u093e \u0915\u094b \u092e\u093f\u0932\u093e"},
