gDT(){return"\u041d\u0435 \u0437\u0430\u043a\u0440\u0438\u0432\u0430\u0439\u0442\u0435 \u0437\u0430\u0441\u0442\u043e\u0441\u0443\u043d\u043e\u043a \u0434\u043e \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u044f \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f \u0430\u0431\u043e \u0431\u0435\u0437\u043f\u0435\u0447\u043d\u043e \u043f\u0440\u0438\u0437\u0443\u043f\u0438\u043d\u0456\u0442\u044c \u043f\u0440\u043e\u0446\u0435\u0441."},
gDV(){return"\u041f\u0456\u0434\u0433\u043e\u0442\u043e\u0432\u043a\u0430 \u0432\u0438\u0434\u0430\u043b\u0435\u043d\u043d\u044f\u2026"},
DU(a,b,c){return"\u0412\u0438\u0434\u0430\u043b\u0435\u043d\u043e \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u044c: "+a+" \u0456\u0437 "+b+". \u0417\u0430\u043b\u0438\u0448\u0438\u043b\u043e\u0441\u044f: "+c+"."},
gDQ(){return"\u041f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0454\u043c\u043e \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u0456 \u0433\u043e\u0442\u0443\u0454\u043c\u043e \u043e\u0447\u0438\u0449\u0435\u043d\u043d\u044f\u2026"},
gDP(){return"\u0412\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u0441\u0442\u0432\u043e\u0440\u0435\u043d\u0456 \u0432\u0430\u043c\u0438 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0442\u0430 \u0437\u043d\u0435\u043e\u0441\u043e\u0431\u043b\u044e\u0454\u043c\u043e \u0432\u0430\u0448\u0443 \u0443\u0447\u0430\u0441\u0442\u044c \u0443 \u0447\u0443\u0436\u0438\u0445 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f\u0445\u2026"},
