gDL(){return"\u041f\u0435\u0440\u0435\u0432\u043e\u0434\u0438\u043c\u043e \u0441\u043f\u0456\u043b\u044c\u043d\u0435 \u043b\u0438\u0441\u0442\u0443\u0432\u0430\u043d\u043d\u044f \u0432 \u0440\u0435\u0436\u0438\u043c \u0447\u0438\u0442\u0430\u043d\u043d\u044f \u0442\u0430 \u0432\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u0434\u0430\u043d\u0456 \u043f\u0440\u043e \u0432\u0430\u0441\u2026"},
gDO(){return"\u0417\u043d\u0435\u043e\u0441\u043e\u0431\u043b\u044e\u0454\u043c\u043e \u0441\u043f\u0456\u043b\u044c\u043d\u0456 \u0441\u043f\u043e\u0432\u0456\u0449\u0435\u043d\u043d\u044f \u0442\u0430 \u0432\u0438\u0434\u0430\u043b\u044f\u0454\u043c\u043e \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456 \u0434\u0430\u043d\u0456 \u0434\u043e\u0441\u0442\u0430\u0432\u043a\u0438\u2026"},
