JW(a){return"\u041f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e \u0434\u043b\u044f \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \xab"+a+"\xbb \u0432\u0456\u0434\u043a\u043b\u0438\u043a\u0430\u043d\u043e."},
